mapper.select:
SELECT 'turn:' || execution_id FROM byai_group_chat_turn WHERE group_session_id=#{groupId} AND source_message_id=#{sourceId}
UNION ALL
SELECT 'execution:' || execution_id FROM byai_group_chat_execution e WHERE group_session_id=#{groupId}
  AND source_message_id=#{sourceId} AND status <> 'CONVERSATION'
  AND NOT EXISTS (SELECT 1 FROM byai_group_chat_turn t WHERE t.anchor_execution_id=e.execution_id)

WITH executions AS ( SELECT 'turn:' || execution_id AS response_id, execution_id, group_session_id, source_message_id, target_agent_id, initiator_user_id, candidate_session_id, status, disposition, create_time, trace_id, answer_message_id, ack_message_id FROM byai_group_chat_turn WHERE group_session_id=#{groupId} UNION ALL SELECT 'execution:' || execution_id, execution_id, group_session_id, source_message_id, target_agent_id, initiator_user_id, candidate_session_id, status, disposition, create_time, trace_id, answer_message_id, ack_message_id FROM byai_group_chat_execution WHERE group_session_id=#{groupId} AND status <> 'CONVERSATION' AND NOT EXISTS (SELECT 1 FROM byai_group_chat_turn u WHERE u.anchor_execution_id=byai_group_chat_execution.execution_id) ) SELECT e.response_id AS "responseId", e.group_session_id AS "groupSessionId", e.source_message_id AS "sourceMessageId", e.target_agent_id AS "targetAgentId", e.initiator_user_id AS "initiatorUserId", e.candidate_session_id AS "candidateSessionId", e.status AS "status", e.disposition AS "disposition", e.create_time AS "createTime", e.trace_id AS "traceId", e.answer_message_id AS "answerMessageId", s.message_content AS "sourceContent", s.metadata AS "sourceMetadata", s.creator_name AS "sourceName", s.creator_id AS "sourceCreatorId", s.create_time AS "sourceCreateTime", s.recalled_at AS "sourceRecalledAt", m.mem_name AS "agentName", t.task_session_id AS "taskSessionId", t.task_name AS "taskName", t.status AS "taskStatus", t.turn_status AS "taskTurnStatus", r.message_id AS "resultMessageId", r.message_content AS "resultContent", r.metadata AS "resultMetadata", r.create_time AS "resultCreateTime", r.recalled_at AS "resultRecalledAt" FROM executions e JOIN byai_message s ON s.message_id=e.source_message_id AND s.session_id=e.group_session_id LEFT JOIN byai_session_member m ON m.session_id=e.group_session_id AND m.mem_obj_type='AGENT' AND m.mem_obj_id=e.target_agent_id LEFT JOIN byai_group_chat_task t ON t.task_session_id=e.candidate_session_id AND t.dispatch_id=e.execution_id LEFT JOIN byai_message r ON r.message_id=e.answer_message_id AND r.session_id=e.group_session_id
WHERE (t.status IS NULL OR t.status <> 'PRIVATE')
AND e.response_id IN #{id}
AND e.response_id > #{cursor} AND e.status IN ('QUEUED','RUNNING') AND e.disposition <> 'TASK'
ORDER BY e.response_id LIMIT #{limit}
